function normalizeUrl(value = '') {
  return String(value).toLowerCase();
}

function normalizeKey(value = '') {
  return String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function contextMatches(item, context = {}) {
  if (!item.careerKeys?.length) return true;
  const haystack = normalizeKey([
    context.career,
    context.programName,
    context.title,
    context.university,
  ].filter(Boolean).join(' '));
  return item.careerKeys.some(key => haystack.includes(normalizeKey(key)));
}

function rowsToCourses(rows, evidence) {
  return rows.map(([nombreCurso, ciclo, metadata = null]) => {
    const hasMetadata = metadata && typeof metadata === 'object' && Object.keys(metadata).length > 0;
    return {
      ciclo: String(ciclo),
      nombreCurso,
      evidencia: hasMetadata ? `${evidence} | ${JSON.stringify(metadata)}` : evidence,
    };
  });
}

